const keys = Object.keys(english).sort((a, b) => b.length - a.length);
const pattern = new RegExp(keys.map(key => key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|"), "g");
function translate(text) {
  if (locale === "zh") return text;
  if (Object.hasOwn(english, text)) return english[text];
  const punctuation = { "，": ", ", "。": ".", "；": "; ", "：": ": ", "（": "(", "）": ")", "“": '"', "”": '"', "、": ", " };
  return text.replace(pattern, key => english[key]).replace(/[，。；：（）“”、]/g, mark => punctuation[mark]);
}

// Tagged templates translate only their static text, before adding values.
export function tr(text, ...values) {
  if (typeof text === "string") return translate(text);
  return text.reduce((result, part, index) => result + translate(part) + (index < values.length ? values[index] : ""), "");
}

document.documentElement.lang = locale === "zh" ? "zh-CN" : "en";
document.title = tr("LayerLine PCB 计算器");
document.querySelector('meta[name="description"]')?.setAttribute("content", tr("PCB 计算器：传输线、走线宽度、过孔、电气间距等计算，计算内核编译为 WebAssembly 在本地运行。"));
document.querySelector("#sideNav")?.setAttribute("aria-label", tr("计算工具"));
if (document.querySelector("#navToggle")) document.querySelector("#navToggle").textContent = tr("☰ 页面");
if (document.querySelector("#pageTitle")) document.querySelector("#pageTitle").textContent = tr("载入中");
for (const link of document.querySelectorAll("[data-calculator-language]")) {
  const url = new URL(location.href);
  url.searchParams.set("lang", link.dataset.calculatorLanguage);
  link.href = url.href;
  if (link.dataset.calculatorLanguage === locale) link.setAttribute("aria-current", "true");
}
